@Component({
  selector: 'app-toggle',
  template: `<button (click)="onClick()">{{ label }}</button>`,
})
export class ToggleComponent {
  @Input() label = 'Toggle';
  @Output() toggled = new EventEmitter<boolean>();
  private on = false;
  onClick() {
    this.on = !this.on;
    this.toggled.emit(this.on);
  }
}
